<?php
require_once '../../config/config.php';
requireAdminModule('settings','write');
$csrf=generateCSRFToken();
$sy=$pdo->query("SELECT school_year_id,label FROM schoolyears WHERE is_current=1 LIMIT 1")->fetch(PDO::FETCH_ASSOC);
$active=$pdo->query("SELECT * FROM teacher_evaluations WHERE status='open' ORDER BY evaluation_id DESC LIMIT 1")->fetch(PDO::FETCH_ASSOC);
$evaluations=$pdo->query("SELECT te.*,sy.label FROM teacher_evaluations te JOIN schoolyears sy ON sy.school_year_id=te.school_year_id ORDER BY te.evaluation_id DESC LIMIT 10")->fetchAll(PDO::FETCH_ASSOC);
$settings=[];
try{$rows=$pdo->query("SELECT setting_key,setting_value FROM system_settings WHERE setting_key='teacher_evaluation_enabled'")->fetchAll(PDO::FETCH_ASSOC);foreach($rows as $r)$settings[$r['setting_key']]=$r['setting_value'];}catch(Throwable $e){}
?>
